pub fn semanticMintIntentClear() void {
    if (z3d.g_semantic_mint_intent) |intent| z3d.jalloc.free(intent.table_json);
    z3d.g_semantic_mint_intent = null;
}

/// Stage semantic output roles for exactly the next face extrusion. The op owns
/// the table only after it succeeds; failure drops the intent without mutating
/// the document, and the operation's journal snapshot remains truly pre-op.
pub fn meshSemanticExtrudeIntentSet(cap_region: u32, wall_region: u32, instance: u32, table_json: []const u8) bool {
    if (!z3d.residentMutationAllowed(.durable_channels)) return false;
    if (cap_region == model_source.NO_SEMANTIC_ID or wall_region == model_source.NO_SEMANTIC_ID or
        table_json.len < 2 or table_json.len > model_source.MAX_SEMANTIC_TABLE_BYTES or
        table_json[0] != '{' or table_json[table_json.len - 1] != '}') return false;
    const owned = z3d.jalloc.dupe(u8, table_json) catch return false;
    z3d.semanticMintIntentClear();
    z3d.g_semantic_mint_intent = .{ .cap_region = cap_region, .wall_region = wall_region, .instance = instance, .table_json = owned };
    return true;
}

pub fn faceExtrudePosKey(p: [3]f32) u64 {
    const q: [3]f32 = .{ p[0] + 0.0, p[1] + 0.0, p[2] + 0.0 };
    var h = std.hash.Wyhash.init(0xe47d);
    h.update(std.mem.asBytes(&q));
    return h.final();
}

pub fn faceEntityContains(e: z3d.FaceExtrudeEntity, f: u32) bool {
    return if (e.grouped) model_source.faceGroupOf(f) == e.group else f == e.face;
}

pub const FaceExtrudeBoundaryPoint = struct { position: [3]f32, logical_id: u32 };

pub fn chainExtrudeBoundary(
    verts: []const f32,
    tri_count: u32,
    entity: z3d.FaceExtrudeEntity,
    logical: *const z3d.LogicalRowsBuilder,
    out: *std.ArrayListUnmanaged(z3d.FaceExtrudeBoundaryPoint),
) bool {
    const Dir = struct { from_key: u64, to_key: u64, ukey: u128, from: [3]f32, logical_id: u32 };
    var undirected = std.AutoHashMapUnmanaged(u128, u32){};
    defer undirected.deinit(std.heap.c_allocator);
    var dirs: std.ArrayListUnmanaged(Dir) = .empty;
    defer dirs.deinit(std.heap.c_allocator);

    var f: u32 = 0;
    while (f < tri_count) : (f += 1) {
        if (!z3d.faceEntityContains(entity, f)) continue;
        const base = @as(usize, f) * 24;
        if (base + 24 > verts.len) return false;
        var k: usize = 0;
        while (k < 3) : (k += 1) {
            const ia = base + k * 8;
            const ib = base + ((k + 1) % 3) * 8;
            const a: [3]f32 = .{ verts[ia + 0], verts[ia + 1], verts[ia + 2] };
            const b: [3]f32 = .{ verts[ib + 0], verts[ib + 1], verts[ib + 2] };
            const ka = z3d.faceExtrudePosKey(a);
            const kb = z3d.faceExtrudePosKey(b);
            if (ka == kb) continue;
            const ukey: u128 = (@as(u128, @min(ka, kb)) << 64) | @max(ka, kb);
            const gop = undirected.getOrPut(std.heap.c_allocator, ukey) catch return false;
            if (!gop.found_existing) gop.value_ptr.* = 0;
            gop.value_ptr.* += 1;
            const logical_id = logical.sourceCorner(f, k) orelse return false;
            dirs.append(std.heap.c_allocator, .{ .from_key = ka, .to_key = kb, .ukey = ukey, .from = a, .logical_id = logical_id }) catch return false;
        }
    }

    const Next = struct { to_key: u64, from: [3]f32, logical_id: u32 };
    var adj = std.AutoHashMapUnmanaged(u64, Next){};
    defer adj.deinit(std.heap.c_allocator);
    var boundary_n: u32 = 0;
    var start_key: u64 = 0;
    var have_start = false;
    for (dirs.items) |de| {
        if ((undirected.get(de.ukey) orelse 0) != 1) continue;
        boundary_n += 1;
        const gop = adj.getOrPut(std.heap.c_allocator, de.from_key) catch return false;
        if (gop.found_existing) return false;
        gop.value_ptr.* = .{ .to_key = de.to_key, .from = de.from, .logical_id = de.logical_id };
        if (!have_start) {
            start_key = de.from_key;
            have_start = true;
        }
    }
    if (!have_start or boundary_n < 3) return false;

    var cur = start_key;
    var count: u32 = 0;
    while (count < boundary_n) {
        const e = adj.get(cur) orelse return false;
        out.append(std.heap.c_allocator, .{ .position = e.from, .logical_id = e.logical_id }) catch return false;
        count += 1;
        cur = e.to_key;
        if (cur == start_key) break;
    }
    return cur == start_key and count == boundary_n;
}

pub fn faceLoopNormal(loop: []const z3d.FaceExtrudeBoundaryPoint) [3]f32 {
    var n: [3]f32 = .{ 0, 0, 0 };
    for (loop, 0..) |item, i| {
        const cur = item.position;
        const nxt = loop[(i + 1) % loop.len].position;
        n[0] += (cur[1] - nxt[1]) * (cur[2] + nxt[2]);
        n[1] += (cur[2] - nxt[2]) * (cur[0] + nxt[0]);
        n[2] += (cur[0] - nxt[0]) * (cur[1] + nxt[1]);
    }
    const l = @sqrt(z3d.vdot(n, n));
    if (l > 1e-8) return .{ n[0] / l, n[1] / l, n[2] / l };
    if (loop.len >= 3) return z3d.normalOf(loop[0].position, loop[1].position, loop[2].position);
    return .{ 0, 1, 0 };
}

pub fn faceLoopCentroid(loop: []const z3d.FaceExtrudeBoundaryPoint) [3]f32 {
    var c: [3]f32 = .{ 0, 0, 0 };
    for (loop) |point| c = z3d.vadd(c, point.position);
    const inv = if (loop.len > 0) 1.0 / @as(f32, @floatFromInt(loop.len)) else 1.0;
    return z3d.vmul(c, inv);
}

pub fn appendFaceColor(list: *std.ArrayListUnmanaged(u8), c: [4]u8) bool {
    list.appendSlice(std.heap.c_allocator, c[0..]) catch return false;
    return true;
}

/// req_2644/req_3314: an edge op appends faces after retain() resets authored metadata.
/// Restore the grouping, then renormalize from the PRE-OP face→part table plus the
/// selected edges' explicit owner. Never re-infer old ownership from the replaced mesh:
/// a detached seam is position-coincident with its source and that guess can hand every
/// detached face back to the original outliner.
/// `tris_per_face` partitions the appended triangle range into authored faces:
/// the source face first, then one segment per mirror twin. Each segment gets its
/// OWN fresh group id — stamping the whole append with one id fused a twin and its
/// source into a single authored face on opposite ends of the model (req_3804).
/// 0 keeps the whole append as one face (no-mirror callers append exactly one).
pub fn adoptAppendedFaces(old_groups: ?[]const u32, old_parts: ?[]const u32, old_faces: u32, src_part: u32, tris_per_face: u32) bool {
    const og = old_groups orelse return z3d.hostPartCount() == 0; // ungrouped import
    const fc = z3d.g_edit_count / 3;
    if (fc <= old_faces or og.len < old_faces) return false;
    const groups = std.heap.c_allocator.alloc(u32, fc) catch return false;
    defer std.heap.c_allocator.free(groups);
    @memcpy(groups[0..old_faces], og[0..old_faces]);
    const new_id = z3d.nextFreeGroupId(og[0..old_faces]); // max+1, so consecutive ids stay free
    const span = if (tris_per_face == 0) fc - old_faces else tris_per_face;
    for (groups[old_faces..fc], 0..) |*slot, appended| slot.* = new_id + @as(u32, @intCast(appended)) / span;
    model_source.setFaceGroups(groups);
    const pc = z3d.hostPartCount();
    if (pc > 0) {
        const prior = old_parts orelse return false;
        if (prior.len < old_faces or src_part >= pc) return false;
        const fp = std.heap.c_allocator.alloc(u32, fc) catch return false;
        defer std.heap.c_allocator.free(fp);
        @memcpy(fp[0..old_faces], prior[0..old_faces]);
        @memset(fp[old_faces..fc], src_part);
        z3d.renormalizePartRanges(fp, pc);
        // Deep postcondition: every pre-existing face and every appended face still
        // resolves to the owner carried into this transaction. A failed allocation or
        // malformed range table rolls the caller back instead of committing corruption.
        var face: u32 = 0;
        while (face < fc) : (face += 1) {
            if (model_source.partIndexOf(model_source.faceGroupOf(face)) != fp[face]) return false;
        }
    }
    _ = z3d.refreshPaintLayout();
    return true;
}

/// Live mirror editing (req_3796/req_3797): the selection extension that makes a
/// face-mask topology op land on BOTH sides — extrude, delete, flip, glass, paint
/// fill, solidify, detach all route through it. For every fully-selected authored
/// face, find the authored face whose distinct corner positions are exactly the
/// reflection of its own across mesh_edit.MIRROR_PLANE_CENTER (per enabled plane
/// subset) and add its triangles to the mask. Matching is positional and quantized
/// (mesh_edit's MIRROR_Q class), never by triangle tessellation — a twin quad split
/// on the OTHER diagonal still pairs. A face with no complete twin, a twin outside
/// the edit scope, a partially-selected source, or a self-twin (a face straddling
/// the plane) simply doesn't extend — the same honesty as mirrored transforms.
/// Quantized corner-position identity shared by the live mirror twin extension and the
/// retroactive mirror repairs — the same tolerance class as mesh_edit's MIRROR_Q.
pub const mirror_corners = struct {
    pub const Q: f32 = 1000.0;
    pub const Key = [3]i32;
    pub fn quant(p: [3]f32) Key {
        return .{
            @intFromFloat(@round(p[0] * Q)),
            @intFromFloat(@round(p[1] * Q)),
            @intFromFloat(@round(p[2] * Q)),
        };
    }
    pub fn corner(verts: []const f32, face: u32, slot: usize) [3]f32 {
        const base = (@as(usize, face) * 3 + slot) * 8;
        return .{ verts[base], verts[base + 1], verts[base + 2] };
    }
    pub fn posLess(a: Key, b: Key) bool {
        inline for (0..3) |axis| {
            if (a[axis] != b[axis]) return a[axis] < b[axis];
        }
        return false;
    }
    pub fn keyHash(sorted: []const Key) u64 {
        var h = std.hash.Wyhash.init(0x726a_3796);
        for (sorted) |k| h.update(std.mem.asBytes(&k));
        return h.final();
    }
    /// Dedupe-insert keeping the list sorted — corner sets are tiny.
    pub fn addKey(list: *std.ArrayListUnmanaged(Key), a: std.mem.Allocator, k: Key) bool {
        for (list.items) |have| {
            if (have[0] == k[0] and have[1] == k[1] and have[2] == k[2]) return true;
        }
        list.append(a, k) catch return false;
        var i = list.items.len - 1;
        while (i > 0 and posLess(list.items[i], list.items[i - 1])) : (i -= 1) {
            std.mem.swap(Key, &list.items[i], &list.items[i - 1]);
        }
        return true;
    }
    pub fn sameKeys(a: []const Key, b: []const Key) bool {
        if (a.len != b.len) return false;
        for (a, b) |ka, kb| {
            if (ka[0] != kb[0] or ka[1] != kb[1] or ka[2] != kb[2]) return false;
        }
        return true;
    }
    /// Reflect a quantized key across MIRROR_PLANE_CENTER on the axes in `subset`.
    pub fn reflect(k: Key, subset: u8) Key {
        var r = k;
        inline for (0..3) |axis| {
            if (subset & (@as(u8, 1) << @intCast(axis)) != 0) {
                const qc2: i32 = @intFromFloat(@round(mesh_edit.MIRROR_PLANE_CENTER[axis] * 2.0 * Q));
                r[axis] = qc2 - r[axis];
            }
        }
        return r;
    }
};

/// The authored-face identity of a triangle: its group, or itself (high-bit tagged
/// so it can't collide with a real group id) when ungrouped.
pub fn authoredFaceIdOf(grouped: bool, f: u32) u32 {
    if (!grouped) return 0x8000_0000 | f;
    const g = model_source.faceGroupOf(f);
    return if (g == model_source.NO_FACE_GROUP) 0x8000_0000 | f else g;
}

pub fn extendFaceMaskWithMirrorTwins(cur_verts: []const f32, tri_count: u32, mask: []bool) void {
    const mirror_mask = mesh_edit.mirrorMask() & 7;
    if (mirror_mask == 0 or tri_count == 0) return;
    const alloc = std.heap.c_allocator;
    const PosKey = z3d.mirror_corners.Key;
    const has_groups = model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP;
    const helpers = z3d.mirror_corners;
    const aid_of = z3d.authoredFaceIdOf;

    var tris_of = std.AutoHashMapUnmanaged(u32, std.ArrayListUnmanaged(u32)).empty;
    var keys_of = std.AutoHashMapUnmanaged(u32, std.ArrayListUnmanaged(PosKey)).empty;
    defer {
        var t_it = tris_of.valueIterator();
        while (t_it.next()) |list| list.deinit(alloc);
        tris_of.deinit(alloc);
        var k_it = keys_of.valueIterator();
        while (k_it.next()) |list| list.deinit(alloc);
        keys_of.deinit(alloc);
    }
    var f: u32 = 0;
    while (f < tri_count) : (f += 1) {
        if (@as(usize, f) * 24 + 24 > cur_verts.len) return;
        const aid = aid_of(has_groups, f);
        const t_gop = tris_of.getOrPut(alloc, aid) catch return;
        if (!t_gop.found_existing) t_gop.value_ptr.* = .empty;
        t_gop.value_ptr.append(alloc, f) catch return;
        const k_gop = keys_of.getOrPut(alloc, aid) catch return;
        if (!k_gop.found_existing) k_gop.value_ptr.* = .empty;
        var slot: usize = 0;
        while (slot < 3) : (slot += 1) {
            if (!helpers.addKey(k_gop.value_ptr, alloc, helpers.quant(helpers.corner(cur_verts, f, slot)))) return;
        }
    }
    var aid_by_hash = std.AutoHashMapUnmanaged(u64, u32).empty;
    defer aid_by_hash.deinit(alloc);
    var hash_it = keys_of.iterator();
    while (hash_it.next()) |entry| {
        aid_by_hash.put(alloc, helpers.keyHash(entry.value_ptr.items), entry.key_ptr.*) catch return;
    }
    var source_it = tris_of.iterator();
    while (source_it.next()) |entry| {
        var all_masked = true;
        for (entry.value_ptr.items) |tri| {
            if (!mask[tri]) {
                all_masked = false;
                break;
            }
        }
        if (!all_masked) continue;
        const source_keys = (keys_of.get(entry.key_ptr.*) orelse continue).items;
        var subset: u8 = 1;
        while (subset <= 7) : (subset += 1) {
            if ((subset & mirror_mask) != subset) continue;
            var reflected = std.ArrayListUnmanaged(PosKey).empty;
            defer reflected.deinit(alloc);
            for (source_keys) |k| {
                if (!helpers.addKey(&reflected, alloc, helpers.reflect(k, subset))) return;
            }
            const twin_aid = aid_by_hash.get(helpers.keyHash(reflected.items)) orelse continue;
            if (twin_aid == entry.key_ptr.*) continue; // straddles the plane — its own twin
            const twin_keys = keys_of.get(twin_aid) orelse continue;
            if (!helpers.sameKeys(twin_keys.items, reflected.items)) continue; // hash collision
            const twin_tris = tris_of.get(twin_aid) orelse continue;
            var extendable = true;
            for (twin_tris.items) |tri| {
                if (!mesh_edit.faceInScopePub(tri)) {
                    extendable = false;
                    break;
                }
            }
            if (!extendable) continue;
            for (twin_tris.items) |tri| mask[tri] = true;
        }
    }
}

pub fn meshTopoExtrudeFace(distance_raw: f32, taper_degrees_raw: f32) bool {
    defer z3d.semanticMintIntentClear();
    const taper_radians = mesh_edit.extrusionAngleRadiansPub(taper_degrees_raw) orelse return false;
    if (!model_paint.hasTarget()) return false;
    if (mesh_edit.mode() != .face) return false;
    const cur_verts = z3d.g_edit_verts orelse return false;
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) return false;

    const mask = std.heap.c_allocator.alloc(bool, tri_count) catch return false;
    defer std.heap.c_allocator.free(mask);
    const selected = mesh_edit.buildDeleteMask(mask);
    if (selected == 0) return false;
    // Live mirror editing (req_3796): a mirrored extrude is the SAME extrude landing on
    // two faces — each pushes along its own normal. Extend the selection with every
    // selected authored face's mirror twin BEFORE choosing the path, so both sides
    // extrude in one journal transaction. The pre-extension mask survives as the reply
    // mask: only the SOURCE side's cap re-selects, so the follow-up transform moves one
    // side directly and the twin cap follows by reflection instead of moving rigidly.
    var reply_mask: ?[]const bool = null;
    var reply_copy: ?[]bool = null;
    defer if (reply_copy) |copy| std.heap.c_allocator.free(copy);
    if (mesh_edit.mirrorMask() != 0) {
        reply_copy = std.heap.c_allocator.dupe(bool, mask) catch null;
        z3d.extendFaceMaskWithMirrorTwins(cur_verts, tri_count, mask);
        if (reply_copy) |copy| {
            if (!std.mem.eql(bool, copy, mask)) reply_mask = copy;
        }
    }

    const has_groups = model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP;
    var entity: ?z3d.FaceExtrudeEntity = null;
    var multi = false;
    var f: u32 = 0;
    while (f < tri_count) : (f += 1) {
        if (!mask[f]) continue;
        const g = if (has_groups) model_source.faceGroupOf(f) else model_source.NO_FACE_GROUP;
        const grouped = has_groups and g != model_source.NO_FACE_GROUP;
        if (entity) |e| {
            if (grouped and e.grouped and e.group == g) continue;
            multi = true; // more than one authored face — the region path takes it
            continue;
        }
        entity = .{
            .grouped = grouped,
            .group = g,
            .face = f,
            .part = if (grouped) model_source.partIndexOf(g) else model_source.NO_PART,
            .color = z3d.trueFaceColor(f),
            .material = model_source.faceMaterialOf(f),
            .semantic_region = model_source.faceSemanticOf(f).region,
            .semantic_instance = model_source.faceSemanticOf(f).instance,
        };
    }
    const ent = entity orelse return false;
    // Region extrude (req_3763 P1-1, per-patch req_3796): a multi-face selection
    // extrudes as connected shells — each edge-connected patch becomes a translated
    // cap pushed along ITS OWN aggregate normal (a face and its mirror twin are two
    // patches going opposite ways), and walls rise only along each patch boundary.
    // The single-face path below stays byte-identical (mesh-port-parity pins its
    // fixtures).
    if (multi) return z3d.meshTopoExtrudeRegion(mask, tri_count, distance_raw, taper_radians, reply_mask);

    const old_groups: ?[]u32 = if (has_groups) (z3d.captureFaceGroups() orelse return false) else null;
    defer if (old_groups) |g| std.heap.c_allocator.free(g);
    const part_count = z3d.hostPartCount();

    var logical = z3d.LogicalRowsBuilder.init() orelse return false;
    defer logical.deinit();
    var cap_logical = z3d.LogicalCloneMap{};
    defer cap_logical.deinit();

    var loop: std.ArrayListUnmanaged(z3d.FaceExtrudeBoundaryPoint) = .empty;
    defer loop.deinit(std.heap.c_allocator);
    if (!z3d.chainExtrudeBoundary(cur_verts, tri_count, ent, &logical, &loop) or loop.items.len < 3) return false;
    const n = z3d.faceLoopNormal(loop.items);
    const dist = if (@abs(distance_raw) > 1e-6) distance_raw else @max(0.05, z3d.g_orbit.radius * 0.08);
    const off = z3d.vmul(n, dist);
    const center = z3d.faceLoopCentroid(loop.items);
    const straight = @abs(taper_radians) <= mesh_edit.ExtrudeTuning.angle_epsilon_radians;
    var cap_scale: f32 = 1.0;
    if (!straight) {
        var max_radius: f32 = 0;
        for (loop.items) |item| {
            const point = item.position;
            const relative = z3d.vsub(point, center);
            const tangent = z3d.vsub(relative, z3d.vmul(n, z3d.vdot(relative, n)));
            max_radius = @max(max_radius, @sqrt(z3d.vdot(tangent, tangent)));
        }
        cap_scale = mesh_edit.faceExtrudeScalePub(max_radius, dist, taper_radians) orelse return false;
    }

    var out: std.ArrayListUnmanaged(f32) = .empty;
    defer out.deinit(std.heap.c_allocator);
    var groups: std.ArrayListUnmanaged(u32) = .empty;
    defer groups.deinit(std.heap.c_allocator);
    var face_part: std.ArrayListUnmanaged(u32) = .empty;
    defer face_part.deinit(std.heap.c_allocator);
    var colors: std.ArrayListUnmanaged(u8) = .empty;
    defer colors.deinit(std.heap.c_allocator);
    var materials: std.ArrayListUnmanaged(u32) = .empty;
    defer materials.deinit(std.heap.c_allocator);
    var semantic_regions: std.ArrayListUnmanaged(u32) = .empty;
    defer semantic_regions.deinit(std.heap.c_allocator);
    var semantic_instances: std.ArrayListUnmanaged(u32) = .empty;
    defer semantic_instances.deinit(std.heap.c_allocator);

    f = 0;
    while (f < tri_count) : (f += 1) {
        if (mask[f]) continue;
        const base = @as(usize, f) * 24;
        if (base + 24 > cur_verts.len) return false;
        if (!z3d.appendFloats(&out, cur_verts[base .. base + 24])) return false;
        if (!logical.appendSourceFace(f)) return false;
        if (has_groups) {
            const g = old_groups.?[f];
            groups.append(std.heap.c_allocator, g) catch return false;
            if (part_count > 0) face_part.append(std.heap.c_allocator, model_source.partIndexOf(g)) catch return false;
        }
        if (!z3d.appendFaceColor(&colors, z3d.trueFaceColor(f))) return false;
        materials.append(std.heap.c_allocator, model_source.faceMaterialOf(f)) catch return false;
        const semantic = model_source.faceSemanticOf(f);
        semantic_regions.append(std.heap.c_allocator, semantic.region) catch return false;
        semantic_instances.append(std.heap.c_allocator, semantic.instance) catch return false;
    }

    var next_group: u32 = if (has_groups) @intCast(z3d.maxGroupId(old_groups.?) + 1) else 0;
    const cap_group = if (has_groups) ent.group else model_source.NO_FACE_GROUP;
    const cap_start_face: u32 = @intCast(out.items.len / 24);

    var i: usize = 1;
    while (i + 1 < loop.items.len) : (i += 1) {
        const a = if (straight) z3d.vadd(loop.items[0].position, off) else mesh_edit.faceExtrudePointPub(loop.items[0].position, center, n, dist, cap_scale);
        const b = if (straight) z3d.vadd(loop.items[i].position, off) else mesh_edit.faceExtrudePointPub(loop.items[i].position, center, n, dist, cap_scale);
        const c = if (straight) z3d.vadd(loop.items[i + 1].position, off) else mesh_edit.faceExtrudePointPub(loop.items[i + 1].position, center, n, dist, cap_scale);
        const a_id = cap_logical.getOrMint(&logical, 0, loop.items[0].logical_id) orelse return false;
        const b_id = cap_logical.getOrMint(&logical, 0, loop.items[i].logical_id) orelse return false;
        const c_id = cap_logical.getOrMint(&logical, 0, loop.items[i + 1].logical_id) orelse return false;
        if (!z3d.appendTriLogical(&out, &logical, a, b, c, .{ a_id, b_id, c_id })) return false;
        if (has_groups) {
            groups.append(std.heap.c_allocator, cap_group) catch return false;
            if (part_count > 0) face_part.append(std.heap.c_allocator, ent.part) catch return false;
        }
        if (!z3d.appendFaceColor(&colors, ent.color)) return false;
        materials.append(std.heap.c_allocator, ent.material) catch return false;
        semantic_regions.append(std.heap.c_allocator, if (z3d.g_semantic_mint_intent) |intent| intent.cap_region else ent.semantic_region) catch return false;
        semantic_instances.append(std.heap.c_allocator, if (z3d.g_semantic_mint_intent) |intent| intent.instance else ent.semantic_instance) catch return false;
    }

    i = 0;
    while (i < loop.items.len) : (i += 1) {
        const a = loop.items[i].position;
        const b = loop.items[(i + 1) % loop.items.len].position;
        const a2 = if (straight) z3d.vadd(a, off) else mesh_edit.faceExtrudePointPub(a, center, n, dist, cap_scale);
        const b2 = if (straight) z3d.vadd(b, off) else mesh_edit.faceExtrudePointPub(b, center, n, dist, cap_scale);
        const a_id = loop.items[i].logical_id;
        const b_id = loop.items[(i + 1) % loop.items.len].logical_id;
        const a2_id = cap_logical.getOrMint(&logical, 0, a_id) orelse return false;
        const b2_id = cap_logical.getOrMint(&logical, 0, b_id) orelse return false;
        const qc = z3d.vmul(z3d.vadd(z3d.vadd(a, b), z3d.vadd(a2, b2)), 0.25);
        const wn = z3d.normalOf(a, b, b2);
        const side_group = if (has_groups) blk: {
            const g = next_group;
            next_group += 1;
            break :blk g;
        } else model_source.NO_FACE_GROUP;
        const ok = if (z3d.vdot(wn, z3d.vsub(qc, center)) < 0)
            z3d.appendQuadSplitLogical(&out, &logical, a2, b2, b, a, .{ a2_id, b2_id, b_id, a_id })
        else
            z3d.appendQuadSplitLogical(&out, &logical, a, b, b2, a2, .{ a_id, b_id, b2_id, a2_id });
        if (!ok) return false;
        if (has_groups) {
            groups.append(std.heap.c_allocator, side_group) catch return false;
            groups.append(std.heap.c_allocator, side_group) catch return false;
            if (part_count > 0) {
                face_part.append(std.heap.c_allocator, ent.part) catch return false;
                face_part.append(std.heap.c_allocator, ent.part) catch return false;
            }
        }
        if (!z3d.appendFaceColor(&colors, ent.color) or !z3d.appendFaceColor(&colors, ent.color)) return false;
        materials.append(std.heap.c_allocator, indexed_edit_mesh.NO_MATERIAL) catch return false;
        materials.append(std.heap.c_allocator, indexed_edit_mesh.NO_MATERIAL) catch return false;
        const wall_region = if (z3d.g_semantic_mint_intent) |intent| intent.wall_region else ent.semantic_region;
        const wall_instance = if (z3d.g_semantic_mint_intent) |intent| intent.instance else ent.semantic_instance;
        semantic_regions.append(std.heap.c_allocator, wall_region) catch return false;
        semantic_regions.append(std.heap.c_allocator, wall_region) catch return false;
        semantic_instances.append(std.heap.c_allocator, wall_instance) catch return false;
        semantic_instances.append(std.heap.c_allocator, wall_instance) catch return false;
    }

    const new_count: u32 = @intCast(out.items.len / 8);
    if (new_count == z3d.g_edit_count) return false;
    const logical_replacement = logical.replacement(new_count) orelse return false;
    var snap = z3d.journalSnapshotCurrent("extrude face");
    mesh_edit.clearSelection();
    if (!z3d.replaceActiveEditMesh(out.items, new_count, logical_replacement)) {
        z3d.journalDiscard(&snap);
        return false;
    }
    if (has_groups) {
        model_source.setFaceGroups(groups.items);
        if (part_count > 0) z3d.renormalizePartRanges(face_part.items, part_count) else _ = z3d.refreshPaintLayout();
    }
    model_source.setFaceMaterials(materials.items);
    const semantics_installed = if (z3d.g_semantic_mint_intent) |intent|
        model_source.setSemanticState(semantic_regions.items, semantic_instances.items, intent.table_json)
    else
        model_source.setFaceSemantics(semantic_regions.items, semantic_instances.items);
    if (!semantics_installed) {
        if (snap) |*before| _ = z3d.journalInstall(before);
        z3d.journalDiscard(&snap);
        return false;
    }
    model_paint.applyColors(colors.items);
    if (model_source.colors()) |src| {
        const nbytes = @min(src.len, colors.items.len);
        if (nbytes > 0) @memcpy(src[0..nbytes], colors.items[0..nbytes]);
    }
    const cap_group_after = if (has_groups) model_source.faceGroupOf(cap_start_face) else model_source.NO_FACE_GROUP;
    z3d.ensureGlassTrailing();
    if (cap_group_after != model_source.NO_FACE_GROUP) {
        _ = mesh_edit.selectFacesByGroupRange(cap_group_after, cap_group_after + 1, false);
    } else {
        _ = mesh_edit.selectFaceByIndex(cap_start_face, false);
    }
    mesh_edit.setMode(.face);
    z3d.journalCommit(&snap);
    return true;
}

/// Region extrude (req_3763 P1-1, per-patch req_3796) — the multi-face half of
/// meshTopoExtrudeFace. The selection is split into edge-connected PATCHES, and each
/// patch translates along its OWN area-weighted average normal to become a cap — so a
/// face and its mirror twin are two patches pushing opposite ways, the same extrude
/// on two faces (there is no single "selection direction" to average away). Every
/// authored face survives with its own group/colour/material/UVs/semantics (the
/// 24-float rows copy verbatim, only positions shift). New side walls rise ONLY
/// along each patch boundary — edges used by exactly one selected face — wound
/// outward by the owning face's own winding, so interior edges never grow walls and
/// a 6-quad panel extrudes as one shell instead of six boxes. Refusals (atomic,
/// nothing mutates): a wire/degenerate face in the selection, a patch spanning
/// parts or a selection mixing grouped/ungrouped faces, a non-manifold selection
/// edge (3+ selected uses), and a closed or folded patch (no boundary, or no net
/// normal to extrude along). `reply_mask` (mirror extension, req_3797) narrows the
/// reply selection to the SOURCE side's caps — the twin caps stay unselected so the
/// follow-up transform mirrors them by reflection instead of moving them rigidly.
pub fn meshTopoExtrudeRegion(mask: []const bool, tri_count: u32, distance_raw: f32, taper_radians: f32, reply_mask: ?[]const bool) bool {
    const alloc = std.heap.c_allocator;
    const cur_verts = z3d.g_edit_verts orelse return false;
    const mesh_grouped = model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP;

    const EdgeKey = [6]u32; // canonical (min,max) pair of exact corner-position bits
    const keys = struct {
        pub fn corner(verts: []const f32, face: u32, slot: usize) [3]u32 {
            const base = (@as(usize, face) * 3 + slot) * 8;
            return .{ @bitCast(verts[base]), @bitCast(verts[base + 1]), @bitCast(verts[base + 2]) };
        }
        pub fn edge(a: [3]u32, b: [3]u32) EdgeKey {
            const a_first = std.mem.order(u32, &a, &b) != .gt;
            var out: EdgeKey = undefined;
            @memcpy(out[0..3], if (a_first) &a else &b);
            @memcpy(out[3..6], if (a_first) &b else &a);
            return out;
        }
        pub fn pos(verts: []const f32, face: u32, slot: usize) [3]f32 {
            const base = (@as(usize, face) * 3 + slot) * 8;
            return .{ verts[base], verts[base + 1], verts[base + 2] };
        }
    };

    // Union-find over selected triangles: an edge used by two selected faces joins
    // them into one patch. Path-halving keeps it near-constant.
    const parent = alloc.alloc(u32, tri_count) catch return false;
    defer alloc.free(parent);
    for (parent, 0..) |*p, i| p.* = @intCast(i);
    const uf = struct {
        pub fn find(pa: []u32, start: u32) u32 {
            var x = start;
            while (pa[x] != x) {
                pa[x] = pa[pa[x]];
                x = pa[x];
            }
            return x;
        }
        pub fn join(pa: []u32, a: u32, b: u32) void {
            const ra = find(pa, a);
            const rb = find(pa, b);
            if (ra != rb) pa[rb] = ra;
        }
    };

    // Validate the selection and census its edges in one pass. Coincident corners
    // are bit-identical within a part (the same fact canonicalFaceBits relies on),
    // so exact position bits are the weld-correct edge identity here.
    const EdgeUse = struct { count: u32, face: u32 };
    var census = std.AutoHashMapUnmanaged(EdgeKey, EdgeUse).empty;
    defer census.deinit(alloc);
    var f: u32 = 0;
    while (f < tri_count) : (f += 1) {
        if (!mask[f]) continue;
        const base = @as(usize, f) * 24;
        if (base + 24 > cur_verts.len) return false;
        if (z3d.canonicalFaceBits(cur_verts, f) == null) return false; // wire faces never extrude
        if (mesh_grouped) {
            const g = model_source.faceGroupOf(f);
            if (g == model_source.NO_FACE_GROUP) return false;
        }
        var slot: usize = 0;
        while (slot < 3) : (slot += 1) {
            const key = keys.edge(keys.corner(cur_verts, f, slot), keys.corner(cur_verts, f, (slot + 1) % 3));
            const gop = census.getOrPut(alloc, key) catch return false;
            if (!gop.found_existing) {
                gop.value_ptr.* = .{ .count = 0, .face = f };
            } else {
                uf.join(parent, gop.value_ptr.face, f);
            }
            gop.value_ptr.count += 1;
            if (gop.value_ptr.count > 2) return false; // non-manifold inside the selection
        }
    }
    var boundary_edges: u32 = 0;
    var census_it = census.valueIterator();
    while (census_it.next()) |use| {
        if (use.count == 1) boundary_edges += 1;
    }
    if (boundary_edges == 0) return false; // a closed selection has no rim to wall

    // Per patch: the area-weighted normal (accumulated in face scan order, so a
    // single-patch selection sums bit-identically to the pre-patch code) and the one
    // part the whole patch must live in.
    const Patch = struct {
        normal: [3]f32,
        part: u32,
        off: [3]f32,
        center_sum: [3]f32,
        center: [3]f32,
        corner_count: u32,
        max_radius: f32,
        scale: f32,
    };
    var patches = std.AutoHashMapUnmanaged(u32, Patch).empty;
    defer patches.deinit(alloc);
    f = 0;
    while (f < tri_count) : (f += 1) {
        if (!mask[f]) continue;
        const face_part = if (mesh_grouped) model_source.partIndexOf(model_source.faceGroupOf(f)) else model_source.NO_PART;
        const gop = patches.getOrPut(alloc, uf.find(parent, f)) catch return false;
        if (!gop.found_existing) {
            gop.value_ptr.* = .{
                .normal = .{ 0, 0, 0 },
                .part = face_part,
                .off = .{ 0, 0, 0 },
                .center_sum = .{ 0, 0, 0 },
                .center = .{ 0, 0, 0 },
                .corner_count = 0,
                .max_radius = 0,
                .scale = 1,
            };
        } else if (gop.value_ptr.part != face_part) {
            return false; // one part per shell
        }
        const p0 = keys.pos(cur_verts, f, 0);
        const p1 = keys.pos(cur_verts, f, 1);
        const p2 = keys.pos(cur_verts, f, 2);
        gop.value_ptr.normal = z3d.vadd(gop.value_ptr.normal, z3d.vcross(z3d.vsub(p1, p0), z3d.vsub(p2, p0))); // area-weighted
        gop.value_ptr.center_sum = z3d.vadd(gop.value_ptr.center_sum, z3d.vadd(p0, z3d.vadd(p1, p2)));
        gop.value_ptr.corner_count += 3;
    }
    const dist = if (@abs(distance_raw) > 1e-6) distance_raw else @max(0.05, z3d.g_orbit.radius * 0.08);
    const straight = @abs(taper_radians) <= mesh_edit.ExtrudeTuning.angle_epsilon_radians;
    var patch_it = patches.valueIterator();
    while (patch_it.next()) |patch| {
        const nlen = @sqrt(z3d.vdot(patch.normal, patch.normal));
        if (nlen < 1e-9) return false; // folded patch — no net direction
        patch.normal = z3d.vmul(patch.normal, 1.0 / nlen);
        if (patch.corner_count == 0) return false;
        patch.center = z3d.vmul(patch.center_sum, 1.0 / @as(f32, @floatFromInt(patch.corner_count)));
        patch.off = z3d.vmul(patch.normal, dist);
    }
    if (!straight) {
        f = 0;
        while (f < tri_count) : (f += 1) {
            if (!mask[f]) continue;
            const patch = patches.getPtr(uf.find(parent, f)) orelse return false;
            var slot: usize = 0;
            while (slot < 3) : (slot += 1) {
                const relative = z3d.vsub(keys.pos(cur_verts, f, slot), patch.center);
                const tangent = z3d.vsub(relative, z3d.vmul(patch.normal, z3d.vdot(relative, patch.normal)));
                patch.max_radius = @max(patch.max_radius, @sqrt(z3d.vdot(tangent, tangent)));
            }
        }
        patch_it = patches.valueIterator();
        while (patch_it.next()) |patch| {
            patch.scale = mesh_edit.faceExtrudeScalePub(patch.max_radius, dist, taper_radians) orelse return false;
        }
    }

    const old_groups: ?[]u32 = if (mesh_grouped) (z3d.captureFaceGroups() orelse return false) else null;
    defer if (old_groups) |g| alloc.free(g);
    const part_count = z3d.hostPartCount();

    var logical = z3d.LogicalRowsBuilder.init() orelse return false;
    defer logical.deinit();
    var cap_logical = z3d.LogicalCloneMap{};
    defer cap_logical.deinit();

    var out: std.ArrayListUnmanaged(f32) = .empty;
    defer out.deinit(alloc);
    var groups: std.ArrayListUnmanaged(u32) = .empty;
    defer groups.deinit(alloc);
    var face_part: std.ArrayListUnmanaged(u32) = .empty;
    defer face_part.deinit(alloc);
    var colors: std.ArrayListUnmanaged(u8) = .empty;
    defer colors.deinit(alloc);
    var materials: std.ArrayListUnmanaged(u32) = .empty;
    defer materials.deinit(alloc);
    var semantic_regions: std.ArrayListUnmanaged(u32) = .empty;
    defer semantic_regions.deinit(alloc);
    var semantic_instances: std.ArrayListUnmanaged(u32) = .empty;
    defer semantic_instances.deinit(alloc);

    // Unselected faces keep everything.
    f = 0;
    while (f < tri_count) : (f += 1) {
        if (mask[f]) continue;
        const base = @as(usize, f) * 24;
        if (base + 24 > cur_verts.len) return false;
        if (!z3d.appendFloats(&out, cur_verts[base .. base + 24])) return false;
        if (!logical.appendSourceFace(f)) return false;
        if (mesh_grouped) {
            const g = old_groups.?[f];
            groups.append(alloc, g) catch return false;
            if (part_count > 0) face_part.append(alloc, model_source.partIndexOf(g)) catch return false;
        }
        if (!z3d.appendFaceColor(&colors, z3d.trueFaceColor(f))) return false;
        materials.append(alloc, model_source.faceMaterialOf(f)) catch return false;
        const semantic = model_source.faceSemanticOf(f);
        semantic_regions.append(alloc, semantic.region) catch return false;
        semantic_instances.append(alloc, semantic.instance) catch return false;
    }

    // The cap: the selected faces themselves, each shifted by ITS patch's offset —
    // rows copy verbatim so UVs, normals, group ids, paint, and per-face semantics
    // all survive the move.
    const cap_start_face: u32 = @intCast(out.items.len / 24);
    var cap_is_source = std.ArrayListUnmanaged(bool).empty;
    defer cap_is_source.deinit(alloc);
    f = 0;
    while (f < tri_count) : (f += 1) {
        if (!mask[f]) continue;
        const patch = patches.get(uf.find(parent, f)) orelse return false;
        cap_is_source.append(alloc, if (reply_mask) |source| source[f] else true) catch return false;
        const base = @as(usize, f) * 24;
        var row: [24]f32 = undefined;
        @memcpy(&row, cur_verts[base .. base + 24]);
        var slot: usize = 0;
        while (slot < 3) : (slot += 1) {
            const point: [3]f32 = .{ row[slot * 8 + 0], row[slot * 8 + 1], row[slot * 8 + 2] };
            const cap_point = if (straight)
                z3d.vadd(point, patch.off)
            else
                mesh_edit.faceExtrudePointPub(point, patch.center, patch.normal, dist, patch.scale);
            row[slot * 8 + 0] = cap_point[0];
            row[slot * 8 + 1] = cap_point[1];
            row[slot * 8 + 2] = cap_point[2];
        }
        if (!z3d.appendFloats(&out, &row)) return false;
        if (logical.enabled()) {
            const namespace = @as(u64, uf.find(parent, f)) + 1;
            var cap_ids: [3]u32 = undefined;
            var logical_corner: usize = 0;
            while (logical_corner < 3) : (logical_corner += 1) {
                const source_id = logical.sourceCorner(f, logical_corner) orelse return false;
                cap_ids[logical_corner] = cap_logical.getOrMint(&logical, namespace, source_id) orelse return false;
            }
            if (!logical.appendTriangle(cap_ids)) return false;
        }
        if (mesh_grouped) {
            const g = old_groups.?[f];
            groups.append(alloc, g) catch return false;
            if (part_count > 0) face_part.append(alloc, model_source.partIndexOf(g)) catch return false;
        }
        if (!z3d.appendFaceColor(&colors, z3d.trueFaceColor(f))) return false;
        materials.append(alloc, model_source.faceMaterialOf(f)) catch return false;
        const semantic = model_source.faceSemanticOf(f);
        semantic_regions.append(alloc, if (z3d.g_semantic_mint_intent) |intent| intent.cap_region else semantic.region) catch return false;
        semantic_instances.append(alloc, if (z3d.g_semantic_mint_intent) |intent| intent.instance else semantic.instance) catch return false;
    }
    const cap_face_count: u32 = @intCast(out.items.len / 24 - cap_start_face);

    // Walls along each patch boundary, in face/edge scan order (deterministic).
    // Each count==1 edge appears exactly once among selected faces, directed a→b by
    // its owner's winding — quad (a, b, b+off, a+off) then faces outward, with off
    // the owning face's patch offset.
    var next_group: u32 = if (mesh_grouped) @intCast(z3d.maxGroupId(old_groups.?) + 1) else 0;
    f = 0;
    while (f < tri_count) : (f += 1) {
        if (!mask[f]) continue;
        const patch = patches.get(uf.find(parent, f)) orelse return false;
        const wall_part = if (mesh_grouped and part_count > 0) model_source.partIndexOf(old_groups.?[f]) else model_source.NO_PART;
        var slot: usize = 0;
        while (slot < 3) : (slot += 1) {
            const key = keys.edge(keys.corner(cur_verts, f, slot), keys.corner(cur_verts, f, (slot + 1) % 3));
            if (((census.get(key) orelse continue).count) != 1) continue;
            const a = keys.pos(cur_verts, f, slot);
            const b = keys.pos(cur_verts, f, (slot + 1) % 3);
            const a2 = if (straight) z3d.vadd(a, patch.off) else mesh_edit.faceExtrudePointPub(a, patch.center, patch.normal, dist, patch.scale);
            const b2 = if (straight) z3d.vadd(b, patch.off) else mesh_edit.faceExtrudePointPub(b, patch.center, patch.normal, dist, patch.scale);
            const a_id = logical.sourceCorner(f, slot) orelse return false;
            const b_id = logical.sourceCorner(f, (slot + 1) % 3) orelse return false;
            const namespace = @as(u64, uf.find(parent, f)) + 1;
            const a2_id = cap_logical.getOrMint(&logical, namespace, a_id) orelse return false;
            const b2_id = cap_logical.getOrMint(&logical, namespace, b_id) orelse return false;
            if (!z3d.appendQuadSplitLogical(&out, &logical, a, b, b2, a2, .{ a_id, b_id, b2_id, a2_id })) return false;
            if (mesh_grouped) {
                groups.append(alloc, next_group) catch return false;
                groups.append(alloc, next_group) catch return false;
                next_group += 1;
                if (part_count > 0) {
                    face_part.append(alloc, wall_part) catch return false;
                    face_part.append(alloc, wall_part) catch return false;
                }
            }
            const wall_color = z3d.trueFaceColor(f);
            if (!z3d.appendFaceColor(&colors, wall_color) or !z3d.appendFaceColor(&colors, wall_color)) return false;
            materials.append(alloc, indexed_edit_mesh.NO_MATERIAL) catch return false;
            materials.append(alloc, indexed_edit_mesh.NO_MATERIAL) catch return false;
            const semantic = model_source.faceSemanticOf(f);
            const wall_region = if (z3d.g_semantic_mint_intent) |intent| intent.wall_region else semantic.region;
            const wall_instance = if (z3d.g_semantic_mint_intent) |intent| intent.instance else semantic.instance;
            semantic_regions.append(alloc, wall_region) catch return false;
            semantic_regions.append(alloc, wall_region) catch return false;
            semantic_instances.append(alloc, wall_instance) catch return false;
            semantic_instances.append(alloc, wall_instance) catch return false;
        }
    }

    const new_count: u32 = @intCast(out.items.len / 8);
    if (new_count == z3d.g_edit_count) return false;
    const logical_replacement = logical.replacement(new_count) orelse return false;
    var snap = z3d.journalSnapshotCurrent("extrude face");
    mesh_edit.clearSelection();
    if (!z3d.replaceActiveEditMesh(out.items, new_count, logical_replacement)) {
        z3d.journalDiscard(&snap);
        return false;
    }
    if (mesh_grouped) {
        model_source.setFaceGroups(groups.items);
        if (part_count > 0) z3d.renormalizePartRanges(face_part.items, part_count) else _ = z3d.refreshPaintLayout();
    }
    model_source.setFaceMaterials(materials.items);
    const semantics_installed = if (z3d.g_semantic_mint_intent) |intent|
        model_source.setSemanticState(semantic_regions.items, semantic_instances.items, intent.table_json)
    else
        model_source.setFaceSemantics(semantic_regions.items, semantic_instances.items);
    if (!semantics_installed) {
        if (snap) |*before| _ = z3d.journalInstall(before);
        z3d.journalDiscard(&snap);
        return false;
    }
    model_paint.applyColors(colors.items);
    if (model_source.colors()) |src| {
        const nbytes = @min(src.len, colors.items.len);
        if (nbytes > 0) @memcpy(src[0..nbytes], colors.items[0..nbytes]);
    }
    z3d.ensureGlassTrailing();
    // The reply selection is the SOURCE side's cap — face indices are append-order
    // stable inside [cap_start_face, cap_start_face + cap_face_count). Twin caps stay
    // unselected so the next transform reflects them instead of dragging them along.
    var cap: u32 = 0;
    var reply_selected = false;
    while (cap < cap_face_count) : (cap += 1) {
        if (cap < cap_is_source.items.len and !cap_is_source.items[cap]) continue;
        _ = mesh_edit.selectFaceByIndex(cap_start_face + cap, reply_selected);
        reply_selected = true;
    }
    mesh_edit.setMode(.face);
    z3d.journalCommit(&snap);
    return true;
}

/// Select the welded edge whose endpoints sit at (p, q) — how a topo op hands its NEW
/// edge to the gizmo so the user can move it without re-clicking (req_3114).
pub fn selectWeldedEdgeAt(p: [3]f32, q: [3]f32) bool {
    return mesh_edit.focusEdgeByEndpoints(p, q);
}

/// True when `p` would land in the same weld class as an existing resident vertex —
/// the topology rebuild would then FUSE the new geometry onto it. Margin 2/WELD_Q
/// covers both weld rules in play (mesh_edit's round-to-cell and the indexed
/// import's eps-ball).
pub fn pointWeldsIntoResidentSoup(p: [3]f32) bool {
    const soup = z3d.g_edit_verts orelse return false;
    const eps = 2.0 / 1024.0;
    var vert: usize = 0;
    while (vert < @as(usize, z3d.g_edit_count)) : (vert += 1) {
        const base = vert * 8;
        const dx = soup[base] - p[0];
        const dy = soup[base + 1] - p[1];
        const dz = soup[base + 2] - p[2];
        if (dx * dx + dy * dy + dz * dz <= eps * eps) return true;
    }
    return false;
}

/// Reflect `p` across the model-origin mirror plane for one enabled-axes subset.
pub fn mirrorReflectPoint(p: [3]f32, subset: u8) [3]f32 {
    var r = p;
    inline for (0..3) |axis| {
        if (subset & (@as(u8, 1) << @intCast(axis)) != 0)
            r[axis] = mesh_edit.MIRROR_PLANE_CENTER[axis] * 2.0 - r[axis];
    }
    return r;
}

/// An extrude may never FUSE (req_3802): the parameterless hotkey stamps the same
/// auto distance every time, so a later stamp's outer corners land bit-equal on an
/// earlier stamp's verts and the rebuild silently welds the "extruded" quad onto
/// unrelated geometry — the user sees "create a face between two edges", and
/// dragging the handed-off edge would tear the neighbour. Nudge the distance until
/// every outer corner — and its enabled mirror reflections, where the twin quads
/// land — sits clear of every resident vertex's weld class.
pub fn extrudeDistanceClearOfResidentVerts(frame: mesh_edit.EdgeExtrusionFrame, requested: f32, angle_radians: f32) f32 {
    const step: f32 = if (requested < 0) -4.0 / 1024.0 else 4.0 / 1024.0;
    const mirror_mask = mesh_edit.mirrorMask() & 7;
    var dist = requested;
    var attempts: u32 = 0;
    attempt: while (attempts < 16) : (attempts += 1) {
        const outer = frame.outerAtAngleRadians(dist, angle_radians);
        for (outer) |corner| {
            if (z3d.pointWeldsIntoResidentSoup(corner)) {
                dist += step;
                continue :attempt;
            }
            var subset: u8 = 1;
            while (subset <= 7) : (subset += 1) {
                if (subset & ~mirror_mask != 0) continue;
                if (z3d.pointWeldsIntoResidentSoup(z3d.mirrorReflectPoint(corner, subset))) {
                    dist += step;
                    continue :attempt;
                }
            }
        }
        break;
    }
    return dist;
}

pub fn meshTopoExtrudeEdge(distance_raw: f32, angle_degrees_raw: f32) bool {
    if (!model_paint.hasTarget()) return false;
    const angle_radians = mesh_edit.extrusionAngleRadiansPub(angle_degrees_raw) orelse return false;
    const edge_idx = mesh_edit.selectedEdgeIndexPub() orelse return false;
    const frame = mesh_edit.edgeExtrusionFramePub(edge_idx) orelse return false;
    const endpoints = mesh_edit.edgeEndpointsPub(edge_idx);
    const src_part = mesh_edit.selectedEdgesCommonPartPub() orelse return false;
    const target_vertex = mesh_edit.selectedVertexIndexPub();
    if (target_vertex) |target| {
        if ((mesh_edit.vertPartPub(target) orelse return false) != src_part) return false;
    }
    const requested = if (@abs(distance_raw) > 1e-6) distance_raw else @max(0.05, z3d.g_orbit.radius * 0.08);
    const dist = z3d.extrudeDistanceClearOfResidentVerts(frame, requested, angle_radians);
    const outer = frame.outerAtAngleRadians(dist, angle_radians);
    const c = outer[0];
    const d = outer[1];

    var logical = z3d.LogicalRowsBuilder.init() orelse return false;
    defer logical.deinit();
    if (!logical.appendAllSource()) return false;
    var mirror_logical = z3d.LogicalCloneMap{};
    defer mirror_logical.deinit();
    const endpoint_ids = [2]u32{
        z3d.logicalIdForEditVertex(&logical, endpoints[0]) orelse return false,
        z3d.logicalIdForEditVertex(&logical, endpoints[1]) orelse return false,
    };

    var verts: std.ArrayListUnmanaged(f32) = .empty;
    if (!z3d.appendCurrentDisplayed(&verts)) {
        verts.deinit(std.heap.c_allocator);
        return false;
    }
    const appended_start = verts.items.len;
    const appended_logical_start = logical.rows.items.len;
    var focus_a = c;
    var focus_b = d;
    var anchored = false;
    var source_outer_ids = [2]?u32{ null, null }; // c, d for the unanchored mirror recipe
    // A retained vertex selection changes the same deep operation into the mixed
    // edge+vertex form: reuse that resident vertex as one outer corner and mint
    // only the opposite open corner. Selecting one of the source edge's own
    // endpoints intentionally collapses the quad to a triangle fan.
    const appended = if (target_vertex) |target| blk: {
        anchored = true;
        const plan = mesh_edit.anchoredEdgeExtrusionPub(
            frame,
            endpoints,
            target,
            mesh_edit.vertPosPub(target),
            dist,
            angle_radians,
        );
        focus_a = plan.outer[plan.shared_index];
        focus_b = plan.outer[plan.open_index];
        const target_id = z3d.logicalIdForEditVertex(&logical, target) orelse return false;
        var outer_ids: [2]u32 = undefined;
        outer_ids[plan.shared_index] = target_id;
        outer_ids[plan.open_index] = logical.mint() orelse return false;
        if (plan.triangle) {
            const open = plan.outer[plan.open_index];
            break :blk z3d.appendTriFacingLogical(
                &verts,
                &logical,
                frame.a,
                frame.b,
                open,
                .{ endpoint_ids[0], endpoint_ids[1], outer_ids[plan.open_index] },
                frame.face_normal,
            );
        }
        break :blk z3d.appendQuadSplitFacingLogical(
            &verts,
            &logical,
            frame.a,
            frame.b,
            plan.outer[1],
            plan.outer[0],
            .{ endpoint_ids[0], endpoint_ids[1], outer_ids[1], outer_ids[0] },
            frame.face_normal,
        );
    } else blk: {
        // Edge ids are position-sorted, not wound. Keep the new coplanar face on
        // the same visible side as its authored neighbour instead of randomly
        // back-culling. Preserve the established zero-angle byte path.
        const c_id = logical.mint() orelse return false;
        const d_id = logical.mint() orelse return false;
        source_outer_ids = .{ c_id, d_id };
        const forward = z3d.vdot(z3d.normalOf(frame.a, frame.b, d), frame.face_normal) >= 0;
        break :blk if (forward)
            z3d.appendQuadSplitLogical(&verts, &logical, frame.a, frame.b, d, c, .{ endpoint_ids[0], endpoint_ids[1], d_id, c_id })
        else
            z3d.appendQuadSplitLogical(&verts, &logical, frame.b, frame.a, c, d, .{ endpoint_ids[1], endpoint_ids[0], c_id, d_id });
    };
    if (!appended) {
        verts.deinit(std.heap.c_allocator);
        return false;
    }
    const source_tris: u32 = @intCast((verts.items.len - appended_start) / 24);
    // Mirror (req_3797): every twin EDGE of the selected edge extrudes the reflected
    // reverse-wound quad in the same commit — one per enabled plane subset. A twin
    // extends only when both twin vertices exist, an editable edge actually runs
    // between them, and it lives in the same part (the append stamps one owner).
    if (mesh_edit.mirrorMask() != 0) {
        var subset: u8 = 1;
        while (subset <= 7) : (subset += 1) {
            const t0 = mesh_edit.mirrorTwinOfVertPub(endpoints[0], subset) orelse continue;
            const t1 = mesh_edit.mirrorTwinOfVertPub(endpoints[1], subset) orelse continue;
            const same_edge = (t0 == endpoints[0] and t1 == endpoints[1]) or (t0 == endpoints[1] and t1 == endpoints[0]);
            // Twin openness must match the source (req_3843): extruding an open edge's
            // twin on a filled side would raise a fin over existing surface, while a
            // deliberate authored-seam extrusion stays bilateral on a matching seam.
            if (!mesh_edit.twinEdgeMatchesSourcePub(endpoints, t0, t1)) continue;
            if ((mesh_edit.vertPartPub(t0) orelse continue) != src_part) continue;
            if ((mesh_edit.vertPartPub(t1) orelse continue) != src_part) continue;
            if (anchored) {
                const target = target_vertex.?;
                const target_twin = mesh_edit.mirrorImageOfVertPub(target, subset) orelse continue;
                if ((mesh_edit.vertPartPub(target_twin) orelse continue) != src_part) continue;
                if (same_edge and target_twin == target) continue;
                // Reflect exactly the source append and reverse every triangle's
                // winding. This covers both the one-triangle endpoint fan and the
                // two-triangle arbitrary-target bridge without a second topology recipe.
                var row: usize = 0;
                while (row < source_tris) : (row += 1) {
                    var corners: [3][3]f32 = undefined;
                    var corner: usize = 0;
                    while (corner < 3) : (corner += 1) {
                        const base = appended_start + row * 24 + corner * 8;
                        corners[corner] = z3d.mirrorReflectPoint(.{ verts.items[base], verts.items[base + 1], verts.items[base + 2] }, subset);
                    }
                    const mirrored_ids: [3]u32 = if (logical.enabled()) blk: {
                        const source_ids = logical.rows.items[appended_logical_start + row * 3 ..][0..3];
                        break :blk .{
                            z3d.mirroredLogicalId(&logical, &mirror_logical, source_ids[0], subset) orelse return false,
                            z3d.mirroredLogicalId(&logical, &mirror_logical, source_ids[2], subset) orelse return false,
                            z3d.mirroredLogicalId(&logical, &mirror_logical, source_ids[1], subset) orelse return false,
                        };
                    } else .{ 0, 0, 0 };
                    if (!z3d.appendTriLogical(&verts, &logical, corners[0], corners[2], corners[1], mirrored_ids)) {
                        verts.deinit(std.heap.c_allocator);
                        return false;
                    }
                }
            } else {
                if (same_edge) continue;
                const ra = z3d.mirrorReflectPoint(frame.a, subset);
                const rb = z3d.mirrorReflectPoint(frame.b, subset);
                const rc = z3d.mirrorReflectPoint(c, subset);
                const rd = z3d.mirrorReflectPoint(d, subset);
                const ra_id = z3d.mirroredLogicalId(&logical, &mirror_logical, endpoint_ids[0], subset) orelse return false;
                const rb_id = z3d.mirroredLogicalId(&logical, &mirror_logical, endpoint_ids[1], subset) orelse return false;
                const rc_id = z3d.mirroredLogicalId(&logical, &mirror_logical, source_outer_ids[0] orelse return false, subset) orelse return false;
                const rd_id = z3d.mirroredLogicalId(&logical, &mirror_logical, source_outer_ids[1] orelse return false, subset) orelse return false;
                // A reflection flips handedness — swap the pairs relative to the source call.
                const forward = z3d.vdot(z3d.normalOf(frame.a, frame.b, d), frame.face_normal) >= 0;
                const twin_appended = if (forward)
                    z3d.appendQuadSplitLogical(&verts, &logical, rb, ra, rc, rd, .{ rb_id, ra_id, rc_id, rd_id })
                else
                    z3d.appendQuadSplitLogical(&verts, &logical, ra, rb, rd, rc, .{ ra_id, rb_id, rd_id, rc_id });
                if (!twin_appended) {
                    verts.deinit(std.heap.c_allocator);
                    return false;
                }
            }
        }
    }
    const owned = verts.toOwnedSlice(std.heap.c_allocator) catch {
        verts.deinit(std.heap.c_allocator);
        return false;
    };
    defer std.heap.c_allocator.free(owned);
    // Grouping bookkeeping BEFORE the replace wipes it (req_2644).
    const new_faces: u32 = @intCast((owned.len - @as(usize, z3d.g_edit_count) * 8) / 24);
    const old_faces = z3d.g_edit_count / 3;
    const old_groups: ?[]u32 = if (model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP) z3d.captureFaceGroups() else null;
    defer if (old_groups) |g| std.heap.c_allocator.free(g);
    const old_parts = z3d.capturePartOfFaces();
    defer if (old_parts) |parts| std.heap.c_allocator.free(parts);
    const materials = z3d.captureFaceMaterials(z3d.g_edit_count / 3 + new_faces) orelse return false;
    defer std.heap.c_allocator.free(materials);
    @memset(materials[old_faces..], indexed_edit_mesh.NO_MATERIAL);
    var semantics = z3d.captureFaceSemantics(old_faces + new_faces) orelse return false;
    defer semantics.deinit();
    const source_semantic = model_source.faceSemanticOf(frame.source_face);
    @memset(semantics.regions[old_faces..], source_semantic.region);
    @memset(semantics.instances[old_faces..], source_semantic.instance);
    if (z3d.hostPartCount() > 0 and src_part == model_source.NO_PART) return false;
    const logical_replacement = logical.replacement(z3d.g_edit_count + new_faces * 3) orelse return false;
    var snap = z3d.journalSnapshotCurrent("extrude edge");
    if (!z3d.replaceActiveEditMesh(owned, z3d.g_edit_count + new_faces * 3, logical_replacement)) {
        z3d.journalDiscard(&snap);
        return false;
    }
    if (!z3d.adoptAppendedFaces(old_groups, old_parts, old_faces, src_part, source_tris)) {
        if (snap) |*before| _ = z3d.journalInstall(before);
        z3d.journalDiscard(&snap);
        return false;
    }
    // Selection handoff is UI state, not mesh integrity. A valid appended face must
    // never be rolled back under a different host key merely because its convenience
    // focus could not be established. The scope rebase above normally makes this
    // succeed; failure leaves a valid committed mesh with no edge selected.
    _ = z3d.selectWeldedEdgeAt(focus_a, focus_b);
    model_source.setFaceMaterials(materials);
    if (!model_source.setFaceSemantics(semantics.regions, semantics.instances)) {
        if (snap) |*before| _ = z3d.journalInstall(before);
        z3d.journalDiscard(&snap);
        return false;
    }
    mesh_edit.setMode(.edge);
    z3d.journalCommit(&snap);
    return true;
}

pub fn findUniqueIndex(items: []const u32, count: u32, v: u32) ?usize {
    var i: u32 = 0;
    while (i < count) : (i += 1) {
        if (items[i] == v) return i;
    }
    return null;
}

pub fn edgeConnects(edges: []const mesh_edit.Edge, a: u32, b: u32) bool {
    for (edges) |e| {
        if ((e[0] == a and e[1] == b) or (e[0] == b and e[1] == a)) return true;
    }
    return false;
}

pub fn closedEdgeLoopOrder(edges: []const mesh_edit.Edge, out: *[4]u32) ?u32 {
    if (edges.len < 3 or edges.len > 4) return null;
    var unique: [4]u32 = undefined;
    var degree = [_]u8{0} ** 4;
    var unique_count: u32 = 0;
    for (edges) |e| {
        var k: usize = 0;
        while (k < 2) : (k += 1) {
            const v = e[k];
            const idx = z3d.findUniqueIndex(unique[0..], unique_count, v) orelse blk: {
                if (unique_count >= unique.len) return null;
                unique[unique_count] = v;
                unique_count += 1;
                break :blk @as(usize, @intCast(unique_count - 1));
            };
            degree[idx] += 1;
        }
    }
    if (unique_count != edges.len) return null;
    var i: u32 = 0;
    while (i < unique_count) : (i += 1) {
        if (degree[i] != 2) return null;
    }

    out[0] = edges[0][0];
    out[1] = edges[0][1];
    var prev = out[0];
    var curr = out[1];
    var n: u32 = 2;
    while (n < unique_count) : (n += 1) {
        var next: ?u32 = null;
        for (edges) |e| {
            if (e[0] == curr and e[1] != prev) next = e[1];
            if (e[1] == curr and e[0] != prev) next = e[0];
        }
        const v = next orelse return null;
        if (v == out[0]) return null;
        out[n] = v;
        prev = curr;
        curr = v;
    }
    if (!z3d.edgeConnects(edges, curr, out[0])) return null;
    return unique_count;
}

// ── Bridge edge loops (req_4271): Create Face over two matched edge runs ─────────
// Two disjoint selected runs — open chains or closed loops — bridge rung by rung
// into a strip of authored quads (the Blender bridge-edge-loops shape: two cylinder
// rims become one continuous tube). The classic Create Face paths (single split
// quad, corner triangle, 3/4-edge loop fill) keep their exact meanings; this only
// claims selections those paths never accepted.

/// 64 edges per run is far beyond any authored rim in the editor; the cap bounds
/// the stack, not the ambition.
pub const BRIDGE_RUN_MAX_EDGES = 64;

pub const BridgeRun = struct {
    /// Ordered so (verts[i], verts[i+1]) is a selected edge; a closed run also
    /// closes (verts[count-1], verts[0]).
    verts: [z3d.BRIDGE_RUN_MAX_EDGES + 1]u32 = undefined,
    count: u32 = 0,
    edge_count: u32 = 0,
    closed: bool = false,
};

pub const BridgeRunPair = struct { a: z3d.BridgeRun, b: z3d.BridgeRun };

/// Decompose the selected edges into exactly two disjoint simple runs when the
/// selection is the bridge shape: 3+ edges, every vertex degree ≤ 2, two connected
/// components. Anything else — including two lone edges, which stay on the classic
/// split-quad path — returns null.
pub fn decomposeBridgeRunPair(edges: []const mesh_edit.Edge) ?z3d.BridgeRunPair {
    if (edges.len < 3 or edges.len > z3d.BRIDGE_RUN_MAX_EDGES * 2) return null;
    const Incidence = struct { e: [2]u32 = .{ 0, 0 }, degree: u8 = 0 };
    var incident = std.AutoHashMapUnmanaged(u32, Incidence).empty;
    defer incident.deinit(std.heap.c_allocator);
    for (edges, 0..) |edge, index| {
        if (edge[0] == edge[1]) return null;
        for (edge) |vertex| {
            const slot = incident.getOrPutValue(std.heap.c_allocator, vertex, .{}) catch return null;
            if (slot.value_ptr.degree >= 2) return null; // a junction is not a simple run
            slot.value_ptr.e[slot.value_ptr.degree] = @intCast(index);
            slot.value_ptr.degree += 1;
        }
    }
    var visited = [_]bool{false} ** (z3d.BRIDGE_RUN_MAX_EDGES * 2);
    var runs: [2]z3d.BridgeRun = .{ .{}, .{} };
    var run_count: u32 = 0;
    for (edges, 0..) |_, seed_index| {
        if (visited[seed_index]) continue;
        if (run_count >= 2) return null;
        const run = &runs[run_count];
        run_count += 1;
        // Walk from the seed edge to one end of its component (or all the way
        // around a loop), then emit the ordered vertex run from there.
        var start_vertex = edges[seed_index][0];
        var start_edge: u32 = @intCast(seed_index);
        var guard: u32 = 0;
        while (guard <= edges.len) : (guard += 1) {
            const info = incident.get(start_vertex) orelse return null;
            if (info.degree == 1) break; // an open end
            const other: u32 = if (info.e[0] == start_edge) info.e[1] else info.e[0];
            if (other == seed_index) break; // came all the way around — closed
            const e = edges[other];
            start_vertex = if (e[0] == start_vertex) e[1] else e[0];
            start_edge = other;
        }
        if (guard > edges.len) return null;
        run.closed = (incident.get(start_vertex) orelse return null).degree == 2;
        // Emit forward from the start, consuming component edges exactly once.
        var vertex = start_vertex;
        var came_from: ?u32 = null;
        while (true) {
            if (run.count > z3d.BRIDGE_RUN_MAX_EDGES) return null;
            run.verts[run.count] = vertex;
            run.count += 1;
            const info = incident.get(vertex) orelse return null;
            var next_edge: ?u32 = null;
            for (info.e[0..info.degree]) |edge_index| {
                if (came_from != null and edge_index == came_from.?) continue;
                if (!visited[edge_index]) next_edge = edge_index;
            }
            const step = next_edge orelse break;
            visited[step] = true;
            run.edge_count += 1;
            const e = edges[step];
            const next_vertex = if (e[0] == vertex) e[1] else e[0];
            if (run.closed and next_vertex == start_vertex) break; // loop closed
            vertex = next_vertex;
            came_from = step;
        }
        if (run.edge_count == 0) return null;
        if (run.closed and run.count != run.edge_count) return null;
        if (!run.closed and run.count != run.edge_count + 1) return null;
    }
    if (run_count != 2) return null;
    if (runs[0].edge_count == 1 and runs[1].edge_count == 1) return null; // classic split-quad territory
    return .{ .a = runs[0], .b = runs[1] };
}

/// Ctrl+right-click (req_4271): extrude the current selection TOWARD the clicked
/// pixel. Face mode measures the click along the selection's aggregate-normal axis
/// (closest point of the click ray to that axis) and runs the ordinary face extrude
/// by that signed distance; edge mode decomposes the click into the selected edge's
/// (outward, face-normal) frame as distance + departure angle. One click, one
/// journal entry — the exact verbs the Extrude dialog applies, aimed by the mouse.
pub fn meshTopoExtrudeToScreen(mx: f32, my: f32) bool {
    z3d.g_topo_refusal = "";
    if (!model_paint.hasTarget()) {
        z3d.topoRefuse("no model is mounted for editing");
        return false;
    }
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const ray = model_paint.cameraRay(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, z3d.vpLocalX(mx), z3d.vpLocalY(my));
    switch (mesh_edit.mode()) {
        .face => {
            const tri_count = z3d.g_edit_count / 3;
            if (tri_count == 0) {
                z3d.topoRefuse("the mesh has no triangles");
                return false;
            }
            const pos = model_paint.positions() orelse {
                z3d.topoRefuse("the mesh positions are unreadable");
                return false;
            };
            const mask = std.heap.c_allocator.alloc(bool, @max(tri_count, model_paint.faceCount())) catch return false;
            defer std.heap.c_allocator.free(mask);
            if (mesh_edit.buildDeleteMask(mask) == 0) {
                z3d.topoRefuse("select the face(s) to extrude first, then ctrl+right-click where the cap should land");
                return false;
            }
            var centroid: [3]f32 = .{ 0, 0, 0 };
            var normal: [3]f32 = .{ 0, 0, 0 };
            var selected: f32 = 0;
            var f: u32 = 0;
            while (f < tri_count) : (f += 1) {
                if (!mask[f]) continue;
                const b = @as(usize, f) * 9;
                if (b + 9 > pos.len) break;
                const p0: [3]f32 = .{ pos[b + 0], pos[b + 1], pos[b + 2] };
                const p1: [3]f32 = .{ pos[b + 3], pos[b + 4], pos[b + 5] };
                const p2: [3]f32 = .{ pos[b + 6], pos[b + 7], pos[b + 8] };
                centroid = z3d.vadd(centroid, z3d.vmul(z3d.vadd(z3d.vadd(p0, p1), p2), 1.0 / 3.0));
                normal = z3d.vadd(normal, z3d.vcross(z3d.vsub(p1, p0), z3d.vsub(p2, p0)));
                selected += 1;
            }
            if (selected == 0) {
                z3d.topoRefuse("select the face(s) to extrude first, then ctrl+right-click where the cap should land");
                return false;
            }
            centroid = z3d.vmul(centroid, 1.0 / selected);
            const normal_length = @sqrt(z3d.vdot(normal, normal));
            if (normal_length <= 1e-9) {
                z3d.topoRefuse("the selected faces have no aggregate direction to extrude along");
                return false;
            }
            normal = z3d.vmul(normal, 1.0 / normal_length);
            // Closest point between the normal axis through the centroid and the click
            // ray — its signed axis parameter IS the distance the user aimed for.
            const toward = z3d.vsub(centroid, ray.o);
            const axis_dot_ray = z3d.vdot(normal, ray.d);
            const denom = 1.0 - axis_dot_ray * axis_dot_ray;
            if (@abs(denom) < 1e-6) {
                z3d.topoRefuse("the view looks straight down the extrude axis — orbit a little and click again");
                return false;
            }
            const distance = (axis_dot_ray * z3d.vdot(ray.d, toward) - z3d.vdot(normal, toward)) / denom;
            if (@abs(distance) < 1e-4) {
                z3d.topoRefuse("the click lands on the selection itself — click where the extruded cap should end up");
                return false;
            }
            return z3d.meshTopoExtrudeFace(distance, 0);
        },
        .edge => {
            const edge_idx = mesh_edit.selectedEdgeIndexPub() orelse {
                z3d.topoRefuse("extrude-to-cursor needs exactly ONE selected edge");
                return false;
            };
            const frame = mesh_edit.edgeExtrusionFramePub(edge_idx) orelse {
                z3d.topoRefuse("the selected edge has no adjacent surface to derive an extrusion frame from");
                return false;
            };
            const mid = z3d.vmul(z3d.vadd(frame.a, frame.b), 0.5);
            const edge_dir = z3d.vsub(frame.b, frame.a);
            const edge_length = @sqrt(z3d.vdot(edge_dir, edge_dir));
            if (edge_length <= 1e-9) {
                z3d.topoRefuse("the selected edge is degenerate");
                return false;
            }
            // The offset lives in the (outward, face-normal) plane whose normal is the
            // edge direction; the click ray meets that plane at the aimed target.
            const plane_normal = z3d.vmul(edge_dir, 1.0 / edge_length);
            const along = z3d.vdot(ray.d, plane_normal);
            if (@abs(along) < 1e-6) {
                z3d.topoRefuse("the view looks straight along the selected edge — orbit a little and click again");
                return false;
            }
            const t = z3d.vdot(z3d.vsub(mid, ray.o), plane_normal) / along;
            const target = z3d.vadd(ray.o, z3d.vmul(ray.d, t));
            const rel = z3d.vsub(target, mid);
            const u = z3d.vdot(rel, frame.outward);
            const v = z3d.vdot(rel, frame.face_normal);
            const distance = @sqrt(u * u + v * v);
            if (distance < 1e-4) {
                z3d.topoRefuse("the click lands on the edge itself — click where the new edge should end up");
                return false;
            }
            // A click behind the face plane would need >89° of departure; clamp to the
            // extrusion guard instead of refusing a forgiving one-click gesture.
            const angle_degrees = std.math.clamp(
                std.math.radiansToDegrees(std.math.atan2(v, u)),
                -mesh_edit.ExtrudeTuning.maximum_absolute_angle_degrees,
                mesh_edit.ExtrudeTuning.maximum_absolute_angle_degrees,
            );
            return z3d.meshTopoExtrudeEdge(distance, angle_degrees);
        },
        else => {
            z3d.topoRefuse("extrude-to-cursor works in Edge or Face select mode");
            return false;
        },
    }
}

/// Name a Create Face refusal and refuse (req_4205). `meshTopoCreateFaceFromEdges`
/// answered one bool across two dozen exits, so "Create Face did nothing" was the whole
/// diagnosis available to the person holding the mouse — and the only way to narrow it
/// was to press the key again, which mutates on the runs where it works. This is the
/// req_4114 contract ("every early exit names itself") finally applied to this verb;
/// `tools/seat action topo-refusal` already reads the slot.
pub fn refuseCreateFace(why: []const u8) bool {
    z3d.topoRefuse(why);
    return false;
}

pub const MISSING_LOGICAL_ROW =
    "a corner of the fill has no logical row id, and the lookup did not record which of its conditions caused that";
pub const MIRROR_ROW_REFUSAL =
    "the mirrored twin fill has no logical row id on the far side — disarm Mirror Edit to land the source side alone";

/// Refuse a fill whose corner has no single stable row, naming WHICH condition it hit.
/// The `ambiguous` case is the interesting one and the only one the person at the mouse
/// can act on: two coincident logical vertices that were never merged.
pub fn refuseCreateFaceMissingLogicalRow() bool {
    z3d.g_topo_refusal = switch (z3d.g_last_logical_id_failure) {
        .none => z3d.MISSING_LOGICAL_ROW,
        .no_table => "the resident mesh carries no logical row table at all, so no appended corner can be addressed — reload the model",
        .stale_table => |stale| std.fmt.bufPrint(
            &z3d.g_topo_refusal_buf,
            "the logical row table is stale: {d} rows for {d} mesh corners. Reload the model before editing topology.",
            .{ stale.rows, stale.corners },
        ) catch "the logical row table is stale",
        .ambiguous => |split| std.fmt.bufPrint(
            &z3d.g_topo_refusal_buf,
            "vertex {d} is ONE welded point whose face corners carry DIFFERENT logical rows ({d} and {d}), and NEITHER belongs to a face touching the selected edges — so there is no neighbouring surface for the new corner to stay attached to. Include an edge of the surface you want it joined to.",
            .{ split.vertex, split.first, split.second },
        ) catch "a fill corner is welded from two unmerged logical vertices",
        .unused => |vertex| std.fmt.bufPrint(
            &z3d.g_topo_refusal_buf,
            "vertex {d} is not used by any face corner, so it has no logical row to inherit",
            .{vertex},
        ) catch "a fill corner belongs to no face",
    };
    return false;
}

pub fn meshTopoCreateFaceFromEdges() bool {
    z3d.g_topo_refusal = "";
    if (!model_paint.hasTarget()) return z3d.refuseCreateFace("no model is mounted for editing");
    const follow_before = mesh_edit.followSelectedEdgesJson(std.heap.c_allocator, 2);
    defer if (follow_before) |json| std.heap.c_allocator.free(json);
    var selected: [z3d.BRIDGE_RUN_MAX_EDGES * 2]mesh_edit.Edge = undefined;
    const selected_count = mesh_edit.selectedEdgesPub(selected[0..]);
    if (selected_count < 2 or selected_count > selected.len) {
        z3d.g_topo_refusal = std.fmt.bufPrint(
            &z3d.g_topo_refusal_buf,
            "Create Face reads {d} in-scope selected edge(s); it needs 2 to bridge, 3 or 4 to fill a closed loop, or two matched edge runs (up to {d} edges each) to bridge loop-to-loop. A plain click REPLACES the selection — the second pick must be additive. An edge selected outside the active part scope is not counted.",
            .{ selected_count, z3d.BRIDGE_RUN_MAX_EDGES },
        ) catch "Create Face needs 2 selected edges, a closed 3/4-edge loop, or two matched edge runs";
        return false;
    }
    const edges = selected[0..@as(usize, @intCast(selected_count))];
    // Bridge shape (req_4271)? Two disjoint runs claim the bridge path below;
    // everything else keeps the classic paths — including their old 16-edge ceiling.
    const bridge_pair = z3d.decomposeBridgeRunPair(edges);
    if (bridge_pair == null and selected_count > 16) {
        z3d.g_topo_refusal = std.fmt.bufPrint(
            &z3d.g_topo_refusal_buf,
            "Create Face reads {d} in-scope selected edges, which is neither a classic fill (2 edges, or a closed 3/4-edge loop) nor two matched edge runs to bridge — deselect down to one of those shapes.",
            .{selected_count},
        ) catch "Create Face: too many selected edges for any fill shape";
        return false;
    }
    const agreed_normal = mesh_edit.selectedEdgesReferenceNormalPub();

    var logical = z3d.LogicalRowsBuilder.init() orelse
        return z3d.refuseCreateFace("the logical row builder could not start — the resident mesh has no indexable row table");
    defer logical.deinit();
    if (!logical.appendAllSource())
        return z3d.refuseCreateFace("the logical row builder could not read the current mesh rows");
    var mirror_logical = z3d.LogicalCloneMap{};
    defer mirror_logical.deinit();

    var verts: std.ArrayListUnmanaged(f32) = .empty;
    if (!z3d.appendCurrentDisplayed(&verts)) {
        verts.deinit(std.heap.c_allocator);
        return z3d.refuseCreateFace("the current mesh vertices could not be read");
    }
    const appended_logical_start = logical.rows.items.len;

    var ok = false;
    var bridge_rungs: u32 = 0;
    if (bridge_pair) |pair| bridge: {
        if (pair.a.closed != pair.b.closed) {
            z3d.topoRefuse("bridge needs two edge runs of the SAME kind — one selected run is a closed loop and the other is open");
            break :bridge;
        }
        if (pair.a.edge_count != pair.b.edge_count) {
            z3d.g_topo_refusal = std.fmt.bufPrint(
                &z3d.g_topo_refusal_buf,
                "bridge pairs edges one-to-one: the selected runs carry {d} and {d} edges — add or remove cuts so the counts match",
                .{ pair.a.edge_count, pair.b.edge_count },
            ) catch "bridge needs two edge runs with MATCHING edge counts";
            break :bridge;
        }
        const a_run = &pair.a;
        const b_run = &pair.b;
        const rungs = a_run.edge_count;
        // Align run B to run A: the offset (closed runs rotate freely) and direction
        // with the least total rung length is the tube the user is looking at — any
        // other pairing is a twisted bridge nobody asked for.
        var b_index: [z3d.BRIDGE_RUN_MAX_EDGES + 1]u32 = undefined;
        {
            const n = b_run.count;
            var best_cost: f32 = std.math.inf(f32);
            var best_offset: u32 = 0;
            var best_reverse = false;
            const offsets: u32 = if (a_run.closed) n else 1;
            var offset: u32 = 0;
            while (offset < offsets) : (offset += 1) {
                for ([2]bool{ false, true }) |reverse| {
                    var cost: f32 = 0;
                    var i: u32 = 0;
                    while (i < a_run.count) : (i += 1) {
                        const bi = if (a_run.closed)
                            (if (reverse) (offset + n - (i % n)) % n else (offset + i) % n)
                        else
                            (if (reverse) n - 1 - i else i);
                        cost += z3d.dist2(mesh_edit.vertPosPub(a_run.verts[i]), mesh_edit.vertPosPub(b_run.verts[bi]));
                    }
                    if (cost < best_cost) {
                        best_cost = cost;
                        best_offset = offset;
                        best_reverse = reverse;
                    }
                }
            }
            var i: u32 = 0;
            while (i < a_run.count) : (i += 1) {
                const bi = if (a_run.closed)
                    (if (best_reverse) (best_offset + n - (i % n)) % n else (best_offset + i) % n)
                else
                    (if (best_reverse) n - 1 - i else i);
                b_index[i] = b_run.verts[bi];
            }
        }
        // ONE winding decision for the whole strip, from the first rung any authority
        // resolves — per-rung facing flips would tear the tube at a shading seam.
        var strip_reversed: ?bool = null;
        var authority_rung: u32 = 0;
        while (authority_rung < rungs and strip_reversed == null) : (authority_rung += 1) {
            const a0 = a_run.verts[authority_rung];
            const a1 = a_run.verts[(authority_rung + 1) % a_run.count];
            const b0 = b_index[authority_rung];
            const b1 = b_index[(authority_rung + 1) % a_run.count];
            const candidate = [4]u32{ a0, a1, b1, b0 };
            const reference = agreed_normal orelse
                mesh_edit.bridgeBoundaryReferenceNormalPub(.{ a0, a1 }, .{ b0, b1 }, &candidate) orelse
                mesh_edit.bridgeCrossReferenceNormalPub(.{ a0, a1 }, .{ b0, b1 }, .{ a0, b0 }, .{ a1, b1 }) orelse
                continue;
            const pa = mesh_edit.vertPosPub(a0);
            const pb = mesh_edit.vertPosPub(a1);
            const pc = mesh_edit.vertPosPub(b1);
            const pd = mesh_edit.vertPosPub(b0);
            const area_normal = z3d.vadd(z3d.vcross(z3d.vsub(pb, pa), z3d.vsub(pc, pa)), z3d.vcross(z3d.vsub(pc, pa), z3d.vsub(pd, pa)));
            strip_reversed = z3d.vdot(area_normal, reference) < 0;
        }
        const reversed = strip_reversed orelse {
            z3d.topoRefuse("no rung of the bridge could resolve a winding: neither run's boundary circulation nor its surface normals gave an authority — one side is probably inside-out; flip it and retry");
            break :bridge;
        };
        var append_ok = true;
        var rung: u32 = 0;
        while (rung < rungs) : (rung += 1) {
            const a0 = a_run.verts[rung];
            const a1 = a_run.verts[(rung + 1) % a_run.count];
            const b0 = b_index[rung];
            const b1 = b_index[(rung + 1) % a_run.count];
            const corners = if (reversed) [4]u32{ a0, b0, b1, a1 } else [4]u32{ a0, a1, b1, b0 };
            const ids = [4]u32{
                z3d.fillCornerLogicalId(&logical, corners[0], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                z3d.fillCornerLogicalId(&logical, corners[1], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                z3d.fillCornerLogicalId(&logical, corners[2], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                z3d.fillCornerLogicalId(&logical, corners[3], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
            };
            append_ok = z3d.appendQuadSplitLogical(
                &verts,
                &logical,
                mesh_edit.vertPosPub(corners[0]),
                mesh_edit.vertPosPub(corners[1]),
                mesh_edit.vertPosPub(corners[2]),
                mesh_edit.vertPosPub(corners[3]),
                ids,
            );
            if (!append_ok) break;
        }
        if (append_ok) {
            ok = true;
            bridge_rungs = rungs;
        } else z3d.topoRefuse("a bridge rung resolved its winding but its quad could not be appended");
    } else if (selected_count == 2) {
        if (!z3d.edgeSharesVertex(edges[0], edges[1])) {
            const a = mesh_edit.vertPosPub(edges[0][0]);
            const b = mesh_edit.vertPosPub(edges[0][1]);
            var c = mesh_edit.vertPosPub(edges[1][0]);
            var d = mesh_edit.vertPosPub(edges[1][1]);
            var c_id = edges[1][0];
            var d_id = edges[1][1];
            if (z3d.dist2(a, d) + z3d.dist2(b, c) < z3d.dist2(a, c) + z3d.dist2(b, d)) {
                const tmp = c;
                c = d;
                d = tmp;
                const tmp_id = c_id;
                c_id = d_id;
                d_id = tmp_id;
            }
            // The quad's other two edges carry the winding when the selected pair's
            // own neighbors disagree — a recess fill works from either opposite pair
            // of its loop (req_3840).
            const candidate = [4]u32{ edges[0][0], edges[0][1], d_id, c_id };
            const winding = agreed_normal orelse mesh_edit.bridgeCrossReferenceNormalPub(
                edges[0],
                edges[1],
                .{ edges[0][0], c_id },
                .{ edges[0][1], d_id },
            ) orelse mesh_edit.bridgeBoundaryReferenceNormalPub(edges[0], edges[1], &candidate) orelse
                // A side the quad already shares with the mesh outranks a disagreement
                // between the two selected edges: it is a real surface the new face
                // touches, so it decides the fill outright (req_4204).
                mesh_edit.bridgeConnectingSideReferenceNormalPub(edges[0], edges[1], &candidate);
            if (winding == null) z3d.topoRefuse("the bridge quad has no winding authority: the two selected edges' surfaces disagree on facing, the quad's other two sides are not BOTH present as authored edges whose surfaces agree, boundary circulation across the selected pair disagrees, and no side the quad already shares resolved it either. One of the two surfaces is probably inside-out — flip it and retry.");
            if (winding) |reference| ok = z3d.appendQuadSplitFacingLogical(
                &verts,
                &logical,
                a,
                b,
                d,
                c,
                .{
                    z3d.fillCornerLogicalId(&logical, edges[0][0], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                    z3d.fillCornerLogicalId(&logical, edges[0][1], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                    z3d.fillCornerLogicalId(&logical, d_id, edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                    z3d.fillCornerLogicalId(&logical, c_id, edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                },
                reference,
            );
            if (winding != null and !ok) z3d.topoRefuse("the bridge quad resolved a winding but its geometry could not be appended");
        } else {
            var order: [3]u32 = undefined;
            if (mesh_edit.triangleFromAdjacentEdges(edges[0], edges[1], &order)) {
                // The corner triangle resolves winding like the quad bridge does
                // (req_4685): the agreed neighbor normal when the two surfaces
                // concur, else boundary circulation across the selected pair,
                // else the triangle's third side when it already exists as an
                // authored edge. A corner turning a hard transition — a notch's
                // roof edge against its wall edge — has no averaged normal, but
                // its circulation still has one exact answer.
                const winding = agreed_normal orelse
                    mesh_edit.bridgeBoundaryReferenceNormalPub(edges[0], edges[1], &order) orelse
                    mesh_edit.bridgeConnectingSideReferenceNormalPub(edges[0], edges[1], &order);
                if (winding) |reference_normal| {
                    ok = z3d.appendTriFacingLogical(
                        &verts,
                        &logical,
                        mesh_edit.vertPosPub(order[0]),
                        mesh_edit.vertPosPub(order[1]),
                        mesh_edit.vertPosPub(order[2]),
                        .{
                            z3d.fillCornerLogicalId(&logical, order[0], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                            z3d.fillCornerLogicalId(&logical, order[1], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                            z3d.fillCornerLogicalId(&logical, order[2], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                        },
                        reference_normal,
                    );
                    if (!ok) z3d.topoRefuse("the corner triangle resolved a winding but its geometry could not be appended");
                } else z3d.topoRefuse("the corner triangle has no winding authority: the surfaces beside the two selected edges disagree on facing, boundary circulation across them disagrees, and the triangle's third side is not an authored edge whose face could decide it. One of the surfaces is probably inside-out — flip it and retry.");
            } else z3d.topoRefuse("the two selected edges share a vertex but do not close a triangle — their far endpoints are not joined");
        }
    } else {
        var order: [4]u32 = undefined;
        if (z3d.closedEdgeLoopOrder(edges, &order)) |n| loop_fill: {
            // Same authority ladder for the closed loop (req_4685): the averaged
            // neighbor normal when every selected edge's surface concurs, else the
            // loop's own boundary circulation.
            const winding = agreed_normal orelse mesh_edit.loopBoundaryReferenceNormalPub(order[0..n]);
            const reference_normal = winding orelse {
                z3d.topoRefuse("the loop fill has no winding authority: the surfaces beside the selected edges disagree on facing and their boundary circulation does not agree on one either. One of the surfaces is probably inside-out — flip it and retry.");
                break :loop_fill;
            };
            const p0 = mesh_edit.vertPosPub(order[0]);
            const p1 = mesh_edit.vertPosPub(order[1]);
            const p2 = mesh_edit.vertPosPub(order[2]);
            ok = if (n == 3)
                z3d.appendTriFacingLogical(
                    &verts,
                    &logical,
                    p0,
                    p1,
                    p2,
                    .{
                        z3d.fillCornerLogicalId(&logical, order[0], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                        z3d.fillCornerLogicalId(&logical, order[1], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                        z3d.fillCornerLogicalId(&logical, order[2], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                    },
                    reference_normal,
                )
            else
                z3d.appendQuadSplitFacingLogical(
                    &verts,
                    &logical,
                    p0,
                    p1,
                    p2,
                    mesh_edit.vertPosPub(order[3]),
                    .{
                        z3d.fillCornerLogicalId(&logical, order[0], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                        z3d.fillCornerLogicalId(&logical, order[1], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                        z3d.fillCornerLogicalId(&logical, order[2], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                        z3d.fillCornerLogicalId(&logical, order[3], edges) orelse return z3d.refuseCreateFaceMissingLogicalRow(),
                    },
                    reference_normal,
                );
            if (!ok) z3d.topoRefuse("the loop fill resolved a winding but its geometry could not be appended");
        } else z3d.topoRefuse("the selected edges do not form a CLOSED loop of exactly 3 or 4 edges — past 2 edges that is the only shape Create Face fills");
    }
    if (!ok) {
        verts.deinit(std.heap.c_allocator);
        if (z3d.g_topo_refusal.len == 0) z3d.topoRefuse("no fill shape was produced for this selection");
        return false;
    }
    // Triangle count of the SOURCE face alone — the twin appends below repeat it, and
    // grouping/focus must treat each copy as its own authored face (req_3804).
    const source_tris: u32 = @intCast((verts.items.len - @as(usize, z3d.g_edit_count) * 8) / 24);
    // A bridge strip is MANY authored faces: each rung quad (2 triangles) gets its
    // own group id in adoption, exactly as if the user had created them one by one.
    const tris_per_authored_face: u32 = if (bridge_rungs > 0) 2 else source_tris;
    // Mirror (req_3797): bridge the twin edges too — the appended face rows reflect
    // across the plane with reversed winding, one copy per enabled subset whose twin
    // vertices and edges all exist in the same part.
    if (mesh_edit.mirrorMask() != 0) {
        const src_part_check = mesh_edit.selectedEdgesCommonPartPub();
        const appended_start = @as(usize, z3d.g_edit_count) * 8;
        const appended_len = verts.items.len - appended_start;
        var subset: u8 = 1;
        twin_subsets: while (subset <= 7) : (subset += 1) {
            var self_twin = true;
            for (edges) |edge| {
                // A bridge can terminate on the mirror plane. Its seam endpoint is
                // its own valid reflected image while the other endpoint crosses to
                // the twin boundary edge (req_3838).
                const t0 = mesh_edit.mirrorImageOfVertPub(edge[0], subset) orelse continue :twin_subsets;
                const t1 = mesh_edit.mirrorImageOfVertPub(edge[1], subset) orelse continue :twin_subsets;
                // The twin edge must match the source edge's openness: bridging from an
                // open edge onto a filled twin side stacks a duplicate coincident face
                // over the existing surface (req_3843).
                if (!mesh_edit.twinEdgeMatchesSourcePub(edge, t0, t1)) continue :twin_subsets;
                if (src_part_check) |part| {
                    if ((mesh_edit.vertPartPub(t0) orelse continue :twin_subsets) != part) continue :twin_subsets;
                    if ((mesh_edit.vertPartPub(t1) orelse continue :twin_subsets) != part) continue :twin_subsets;
                }
                const same_edge = (t0 == edge[0] and t1 == edge[1]) or (t0 == edge[1] and t1 == edge[0]);
                if (!same_edge) self_twin = false;
            }
            if (self_twin) continue; // the loop straddles the plane — it is its own twin
            var row: usize = 0;
            while (row * 24 < appended_len) : (row += 1) {
                var corners: [3][3]f32 = undefined;
                var k: usize = 0;
                while (k < 3) : (k += 1) {
                    const base = appended_start + row * 24 + k * 8;
                    corners[k] = .{ verts.items[base], verts.items[base + 1], verts.items[base + 2] };
                    inline for (0..3) |axis| {
                        if (subset & (@as(u8, 1) << @intCast(axis)) != 0)
                            corners[k][axis] = mesh_edit.MIRROR_PLANE_CENTER[axis] * 2.0 - corners[k][axis];
                    }
                }
                const mirrored_ids: [3]u32 = if (logical.enabled()) blk: {
                    const source_ids = logical.rows.items[appended_logical_start + row * 3 ..][0..3];
                    break :blk .{
                        z3d.mirroredLogicalId(&logical, &mirror_logical, source_ids[0], subset) orelse return z3d.refuseCreateFace(z3d.MIRROR_ROW_REFUSAL),
                        z3d.mirroredLogicalId(&logical, &mirror_logical, source_ids[2], subset) orelse return z3d.refuseCreateFace(z3d.MIRROR_ROW_REFUSAL),
                        z3d.mirroredLogicalId(&logical, &mirror_logical, source_ids[1], subset) orelse return z3d.refuseCreateFace(z3d.MIRROR_ROW_REFUSAL),
                    };
                } else .{ 0, 0, 0 };
                if (!z3d.appendTriLogical(&verts, &logical, corners[0], corners[2], corners[1], mirrored_ids)) {
                    verts.deinit(std.heap.c_allocator);
                    return z3d.refuseCreateFace("the mirrored twin fill could not be appended — disarm Mirror Edit to land the source side alone");
                }
            }
        }
    }
    const owned = verts.toOwnedSlice(std.heap.c_allocator) catch {
        verts.deinit(std.heap.c_allocator);
        return z3d.refuseCreateFace("out of memory building the appended vertex buffer");
    };
    defer std.heap.c_allocator.free(owned);
    const added: u32 = @intCast((owned.len / 8) - @as(usize, z3d.g_edit_count));
    // Grouping bookkeeping BEFORE the replace wipes it (req_2644/req_3314): the
    // bridged face joins the one explicit part shared by every selected edge.
    const old_faces = z3d.g_edit_count / 3;
    const old_groups: ?[]u32 = if (model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP) z3d.captureFaceGroups() else null;
    defer if (old_groups) |g| std.heap.c_allocator.free(g);
    const old_parts = z3d.capturePartOfFaces();
    defer if (old_parts) |parts| std.heap.c_allocator.free(parts);
    const materials = z3d.captureFaceMaterials(old_faces + added / 3) orelse
        return z3d.refuseCreateFace("the face material table could not be captured for the appended faces");
    defer std.heap.c_allocator.free(materials);
    @memset(materials[old_faces..], indexed_edit_mesh.NO_MATERIAL);
    var semantics = z3d.captureFaceSemantics(old_faces + added / 3) orelse
        return z3d.refuseCreateFace("the face semantic table could not be captured for the appended faces");
    defer semantics.deinit();
    const src_part = mesh_edit.selectedEdgesCommonPartPub() orelse
        return z3d.refuseCreateFace("the selected edges do not all belong to ONE Outliner part — an edge whose two endpoints sit in different parts, or two edges owned by different parts, has no part for the new face to join. Run `tools/seat action part-ownership` if the Outliner disagrees with the host.");
    if (z3d.hostPartCount() > 0 and src_part == model_source.NO_PART)
        return z3d.refuseCreateFace("this model has Outliner parts, but the selected edges belong to none of them, so the new face would have no owner");
    const inherited_retopo_band = if (z3d.g_retopo_pending_band_generation == z3d.g_edit_generation)
        z3d.g_retopo_pending_band
    else
        mesh_edit.RETOPO_BAND_UNASSIGNED;
    const had_retopo_bands = z3d.g_retopo_manual_bands != null;
    var retopo_bands = z3d.prepareRetopoBandAppend(@intCast(old_faces), @intCast(added / 3), inherited_retopo_band);
    defer if (retopo_bands) |labels| std.heap.c_allocator.free(labels);
    // UV mask zones ride the same carry: appended faces start unassigned (req_4152).
    const had_uv_zone = z3d.g_uv_zone != null;
    var uv_zone_carry = z3d.prepareZoneAppend(&z3d.g_uv_zone, @intCast(old_faces), @intCast(added / 3), z3d.UV_ZONE_UNASSIGNED);
    defer if (uv_zone_carry) |labels| std.heap.c_allocator.free(labels);
    const logical_replacement = logical.replacement(z3d.g_edit_count + added) orelse
        return z3d.refuseCreateFace("the logical row replacement could not be built for the appended faces");
    var snap = z3d.journalSnapshotCurrent("create face");
    const replaced = z3d.replaceActiveEditMesh(owned, z3d.g_edit_count + added, logical_replacement);
    if (replaced) {
        if (!z3d.adoptAppendedFaces(old_groups, old_parts, old_faces, src_part, tris_per_authored_face)) {
            if (snap) |*before| _ = z3d.journalInstall(before);
            z3d.journalDiscard(&snap);
            return z3d.refuseCreateFace("the fill landed but could not be adopted into an authored face group / Outliner part, so it was rolled back");
        }
        model_source.setFaceMaterials(materials);
        if (!model_source.setFaceSemantics(semantics.regions, semantics.instances)) {
            if (snap) |*before| _ = z3d.journalInstall(before);
            z3d.journalDiscard(&snap);
            return z3d.refuseCreateFace("the semantic table refused the appended faces, so the fill was rolled back");
        }
        z3d.commitRetopoBandCarry(had_retopo_bands, &retopo_bands);
        z3d.commitZoneCarry(&z3d.g_uv_zone, had_uv_zone, &uv_zone_carry);
        z3d.g_retopo_pending_band = mesh_edit.RETOPO_BAND_UNASSIGNED;
        z3d.g_retopo_pending_band_generation = 0;
        // Create Face hands the next edit to its result: Face mode + exactly the new
        // SOURCE face selected (a mirror twin is its own authored face and follows
        // bilaterally), so X can reverse an unlucky winding immediately. A bridge
        // keeps its WHOLE strip selected — one X still flips every rung together.
        if (bridge_rungs > 0) {
            const fc = z3d.g_edit_count / 3;
            const strip_mask: ?[]bool = std.heap.c_allocator.alloc(bool, fc) catch null;
            if (strip_mask) |mask_buf| {
                defer std.heap.c_allocator.free(mask_buf);
                @memset(mask_buf, false);
                var t: u32 = old_faces;
                const strip_end = @min(fc, old_faces + source_tris);
                while (t < strip_end) : (t += 1) mask_buf[t] = true;
                _ = mesh_edit.selectFacesByTriangleMask(mask_buf);
            }
        } else _ = mesh_edit.focusCreatedFace(old_faces, source_tris);
        z3d.journalCommit(&snap);
        if (follow_before) |before| {
            if (mesh_edit.followPatchJson(std.heap.c_allocator, null, 2)) |after| {
                defer std.heap.c_allocator.free(after);
                z3d.g_follow_action_queue.append(
                    std.heap.c_allocator,
                    @intFromEnum(mesh_journal_log.ActionKind.create_face),
                    @intFromEnum(z3d.g_mesh_action_source),
                    before,
                    after,
                ) catch {};
            }
        }
    } else {
        z3d.journalDiscard(&snap);
        z3d.topoRefuse("the resident mesh refused to accept the appended fill — the indexed rebuild rejected the result");
    }
    return replaced;
}
